import { randomUUID } from 'node:crypto';

/**
 * Storage keys and buckets. Keys are generated by the server only (never from user input) and keep the
 * format used since Phase 4, so existing database rows stay valid with any driver.
 *
 *   doctor-documents/<doctorId>/<uuid>.<pdf|jpg|png>   → bucket fd-verification
 *   avatars/<userId>/<uuid>.jpg                        → bucket fd-photos
 *   prescriptions/<prescriptionId>/<uuid>.pdf          → bucket fd-prescriptions
 *   medical-documents/<consultationId>/<uuid>.<ext>    → bucket fd-medical
 *   staging: <yyyymmdd>/<uuid>                         → bucket fd-staging (unvalidated uploads; never served)
 */
export const KEY_PATTERN = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.(pdf|jpg|png)$/;
export const STAGING_KEY_PATTERN = /^\d{8}\/[0-9a-f-]{36}$/;

export const BUCKETS = Object.freeze({
  'doctor-documents': { bucket: 'fd-verification', maxBytes: 5 * 1024 * 1024, types: ['application/pdf', 'image/jpeg', 'image/png'] },
  avatars: { bucket: 'fd-photos', maxBytes: 1024 * 1024, types: ['image/jpeg'] },
  prescriptions: { bucket: 'fd-prescriptions', maxBytes: 2 * 1024 * 1024, types: ['application/pdf'] },
  'medical-documents': { bucket: 'fd-medical', maxBytes: 10 * 1024 * 1024, types: ['application/pdf', 'image/jpeg', 'image/png'] },
});
export const STAGING_BUCKET = Object.freeze({ bucket: 'fd-staging', maxBytes: 10 * 1024 * 1024, types: ['application/pdf', 'image/jpeg', 'image/png', 'application/octet-stream'] });

const MIME_FOR_EXT = Object.freeze({ pdf: 'application/pdf', jpg: 'image/jpeg', png: 'image/png' });

/** Validates a server-generated storage key and returns its bucket, size limit, allowed types and content type. Throws on an invalid key or prefix. */
export function assertKey(key) {
  if (typeof key !== 'string' || !KEY_PATTERN.test(key)) throw new Error('Invalid storage key');
  const prefix = key.split('/')[0];
  const target = BUCKETS[prefix];
  if (!target) throw new Error('Unknown storage key prefix');
  return { prefix, ...target, contentType: MIME_FOR_EXT[key.split('.').pop()] };
}

/** Validates a staging key (<yyyymmdd>/<uuid>) and returns it. Throws when invalid. */
export function assertStagingKey(key) {
  if (typeof key !== 'string' || !STAGING_KEY_PATTERN.test(key)) throw new Error('Invalid staging key');
  return key;
}

/** A new random staging path, grouped by UTC day so cleanup can work per day. */
export function newStagingKey(now = new Date()) {
  return `${now.toISOString().slice(0, 10).replace(/-/g, '')}/${randomUUID()}`;
}

/** The yyyymmdd day folder of a staging key (used by cleanup). */
export const stagingDay = (key) => key.slice(0, 8);
